import{_ as t,o,c as i,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-08-13","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-08-13","date":"2025-08-13T00:00:00.000Z","updated":"2025-09-08T00:00:00.000Z","tags":["Ceph","RGW","Bucket Logging","Performance Optimization","Erasure Coding"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-08-13.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-08-13.md","lastUpdated":1780460162000}'),l={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-08-13.md"};function n(r,e,s,c,g,d){return o(),i("div",null,[...e[0]||(e[0]=[a('<p>在2025年8月13日的Ceph RGW重构会议中，讨论了以下关键议题：</p><h3 id="_1-bucket-logging在ec-pool中的问题及解决方案" tabindex="-1">1. Bucket Logging在EC Pool中的问题及解决方案 <a class="header-anchor" href="#_1-bucket-logging在ec-pool中的问题及解决方案" aria-label="Permalink to &quot;1. Bucket Logging在EC Pool中的问题及解决方案&quot;">​</a></h3><ul><li><strong>问题背景</strong>：EC Pool不支持对RADOS对象的原地追加日志记录，这影响了性能。</li><li><strong>现有方案</strong>：将数据写入额外的数据池（replicated pool），但需要用户手动创建<code>storage class</code>。</li><li><strong>讨论要点</strong>： <ul><li><strong>临时方案 vs. 最终方案</strong>：一致同意采用异步复制日志记录到EC Pool，并在提交时创建<code>head object</code>。</li><li><strong>性能优化</strong>：若在replicated pool中，则直接写入；若在EC Pool，则临时写入extra data pool，异步复制到目标池。</li></ul></li><li><strong>后续行动</strong>：Nithia &amp; Yuval将继续实现异步复制逻辑，确保<code>head object</code>正确指向<code>tail objects</code>。</li></ul><h3 id="_2-bucket-listing性能优化" tabindex="-1">2. Bucket Listing性能优化 <a class="header-anchor" href="#_2-bucket-listing性能优化" aria-label="Permalink to &quot;2. Bucket Listing性能优化&quot;">​</a></h3><ul><li><strong>问题背景</strong>：当<code>bucket index</code>包含大量连续的<code>delete markers</code>时，列表操作会显著变慢。</li><li><strong>讨论要点</strong>： <ul><li><strong>优化方向</strong>：保持长连接，发送<code>whitespace</code>防止客户端超时，优化长列表性能。</li></ul></li><li><strong>后续行动</strong>：Jane &amp; Eric将重新评估设计，优先考虑保持标记连续性的方案。</li></ul><h3 id="关键结论" tabindex="-1">关键结论 <a class="header-anchor" href="#关键结论" aria-label="Permalink to &quot;关键结论&quot;">​</a></h3><ul><li><strong>Bucket Logging</strong>：采用异步复制到EC Pool的最终方案。</li><li><strong>Bucket Listing</strong>：优化列表逻辑，减少<code>delete markers</code>的影响。</li></ul><h3 id="下一步计划" tabindex="-1">下一步计划 <a class="header-anchor" href="#下一步计划" aria-label="Permalink to &quot;下一步计划&quot;">​</a></h3><p>| 任务 | 负责人 | 时间节点 | ||--|-| | 实现异步复制逻辑 | Nithia &amp; Yuval | 后续迭代 | | 优化Bucket Listing性能 | Jane &amp; Eric | 待优先级确认 | | 修复GC误删问题 | Nithia (需与Eric协作) | 短期跟进 |</p><p>该会议讨论了Ceph RGW在Bucket Logging和Bucket Listing方面的性能优化和改进方案，并确定了后续的行动计划。</p>',10)])])}const _=t(l,[["render",n]]);export{u as __pageData,_ as default};
